// Builds assets/incident-cache.js for the status page.
//
// The status page normally asks the GitHub API for the incident lists from each
// visitor's browser, and GitHub allows only 60 such requests an hour per IP
// address. This script fetches the same four lists here, with the workflow's
// token, and writes them to a small script the page loads first. That script
// fills the page's own cache, so the homepage makes no GitHub API calls.
//
// Usage: GITHUB_TOKEN=... GITHUB_REPOSITORY=owner/repo node .github/scripts/build-incident-cache.mjs

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";

const [owner, repo] = (process.env.GITHUB_REPOSITORY || "AgentoBOAT/status").split("/");
const token = process.env.GITHUB_TOKEN || "";
const OUT = "assets/incident-cache.js";

// Rewrite the file at least this often even when nothing changed, so the page
// can tell a healthy cache from one that has stopped updating.
const REFRESH_MS = 12 * 60 * 60 * 1000;
// The page ignores a cache older than this and falls back to asking GitHub.
const MAX_AGE_MS = 36 * 60 * 60 * 1000;

// Cache keys and queries, exactly as the status page uses them.
const lists = {
  [`issues-${owner}-${repo}`]: { state: "open", labels: "status" },
  [`scheduled-current-${owner}-${repo}`]: { state: "open", labels: "maintenance" },
  [`closed-issues-${owner}-${repo}`]: { state: "closed", labels: "status" },
  [`maintenance-issues-${owner}-${repo}`]: { state: "closed", labels: "maintenance" },
};

// Only the fields the page reads.
const slim = (issue) => ({
  number: issue.number,
  title: issue.title,
  body: issue.body || "",
  state: issue.state,
  comments: issue.comments,
  created_at: issue.created_at,
  closed_at: issue.closed_at,
  html_url: issue.html_url,
  labels: (issue.labels || []).map((l) => ({ name: typeof l === "string" ? l : l.name })),
});

async function list({ state, labels }) {
  const url =
    `https://api.github.com/repos/${owner}/${repo}/issues` +
    `?state=${state}&filter=all&sort=created&direction=desc&labels=${labels}`;
  const res = await fetch(url, {
    headers: {
      Accept: "application/vnd.github+json",
      "User-Agent": "status-incident-cache",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
  });
  if (!res.ok) throw new Error(`GitHub returned ${res.status} for ${state}/${labels}`);
  return (await res.json()).map(slim);
}

const data = {};
for (const [key, query] of Object.entries(lists)) data[key] = await list(query);

const body = JSON.stringify(data);
const previous = existsSync(OUT) ? readFileSync(OUT, "utf8") : "";
const previousBody = (previous.match(/\/\*data\*\/(.*)\/\*end\*\//s) || [])[1];
const previousAt = Number((previous.match(/\/\*at\*\/(\d+)/) || [])[1] || 0);

if (previousBody === body && Date.now() - previousAt < REFRESH_MS) {
  console.log("incident cache unchanged");
  process.exit(0);
}

const script = `// Generated by .github/scripts/build-incident-cache.mjs. Do not edit.
(function () {
  try {
    var at = /*at*/${Date.now()};
    if (Date.now() - at > ${MAX_AGE_MS}) return;
    var lists = /*data*/${body}/*end*/;
    var now = new Date().toISOString();
    for (var key in lists) {
      localStorage.setItem(key, JSON.stringify({ data: { data: lists[key] }, createdAt: now }));
    }
  } catch (e) {}
})();
`;

mkdirSync("assets", { recursive: true });
writeFileSync(OUT, script);
console.log(`wrote ${OUT}: ` + Object.entries(data).map(([k, v]) => `${k}=${v.length}`).join(", "));
